54	TEST_F(AbiCompatibilityForExeGraphUT, Shape_CheckMemLayoutNotChanged) {
55	  Shape s;
56	  ASSERT_EQ(sizeof(s), kShapeSize);
57	  ASSERT_EQ(static_cast<void *>(&s), static_cast<void *>(&s.dim_num_));
58	
59	  EXPECT_EQ(reinterpret_cast<uintptr_t>(&s.dims_) - reinterpret_cast<uintptr_t>(&s.dim_num_), sizeof(size_t));
60	  EXPECT_EQ(reinterpret_cast<uintptr_t>(&s.reserved_) - reinterpret_cast<uintptr_t>(&s.dims_), 25 * sizeof(int64_t));
61	  EXPECT_EQ(sizeof(s.reserved_), kReservedFieldSize);
62	
63	  EXPECT_EQ(Shape::kMaxDimNum, 25);
64	}
