16	class Chain {
17	 public:
18	  using Deleter = void (*)(void *);
19	  /**
20	   * 获取Chain中保存的数据的指针
21	   * @tparam T 数据类型
22	   * @return 指向数据的指针
23	   */
24	  template <typename T, typename std::enable_if<(sizeof(T) <= sizeof(void *)), int>::type = 0>
25	  const T *GetPointer() const {
26	    return reinterpret_cast<const T *>(any_value_.data.inplace);
27	  }
28	  /**
29	   * 获取Chain中保存的数据的指针
30	   * @tparam T 数据类型
31	   * @return 指向数据的指针
32	   */
33	  template <typename T, typename std::enable_if<(sizeof(T) > sizeof(void *)), int>::type = 0>
34	  const T *GetPointer() const {
35	    return reinterpret_cast<const T *>(any_value_.data.pointer);
36	  }
37	  /**
38	   * 获取Chain中保存的数据的指针
39	   * @tparam T 数据类型
40	   * @return 指向数据的指针
41	   */
42	  template <typename T, typename std::enable_if<(sizeof(T) <= sizeof(void *)), int>::type = 0>
43	  auto GetPointer() -> T * {
44	    return reinterpret_cast<T *>(any_value_.data.inplace);
45	  }
46	  /**
47	   * 获取Chain中保存的数据的指针
48	   * @tparam T 数据类型
49	   * @return 指向数据的指针
50	   */
51	  template <typename T, typename std::enable_if<(sizeof(T) > sizeof(void *)), int>::type = 0>
52	  auto GetPointer() -> T * {
53	    return reinterpret_cast<T *>(any_value_.data.pointer);
54	  }
55	  /**
56	   * 获取Chain中保存的数据的值
57	   * @tparam T 数据类型
58	   * @return 数据的值的引用
59	   */
60	  template <typename T, typename std::enable_if<(sizeof(T) <= sizeof(void *)), int>::type = 0>
61	  const T &GetValue() const {
62	    return *reinterpret_cast<const T *>(any_value_.data.inplace);
63	  }
64	  /**
65	   * 获取Chain中保存的数据的值
66	   * @tparam T 数据类型
67	   * @return 数据的值的引用
68	   */
69	  template <typename T, typename std::enable_if<(sizeof(T) <= sizeof(void *)), int>::type = 0>
70	  auto GetValue() -> T & {
71	    return *reinterpret_cast<T *>(any_value_.data.inplace);
72	  }
73	  /**
74	   * 将数据设置到Chain中。设置数据指针时，会尝试调用deleter将原有保存在Chain的数据删除
75	   * @param data 指向数据的指针
76	   * @param deleter 释放数据的接口，空指针的含义为不需要释放
77	   */
78	  void Set(void *const data, const Chain::Deleter deleter) {
79	    FreeResource();
80	    any_value_.data.pointer = data;
81	    any_value_.deleter = deleter;
82	  }
83	  /**
84	   * 将数据设置到Chain中。设置数据指针时，会尝试调用deleter将原有保存在Chain的数据删除
85	   * @tparam T 数据的类型
86	   * @param data 数据的指针
87	   */
88	  template <typename T, typename std::enable_if<(!std::is_array<T>::value), int>::type = 0>
89	  void SetWithDefaultDeleter(T *data) {
90	    Set(data, reinterpret_cast<FreeCallback>(DefaultDeleter<T>));
91	  }
92	  /**
93	   * 将数据设置到Chain中。设置数据指针时，会尝试调用deleter将原有保存在Chain的数据删除
94	   * @tparam T 数据的类型
95	   * @param data 数据的指针
96	   */
97	  template <typename T, typename PureT = typename std::remove_extent<T>::type,
98	            typename std::enable_if<std::is_array<T>::value, int>::type = 0>
99	  void SetWithDefaultDeleter(PureT *data) {
100	    Set(data, reinterpret_cast<FreeCallback>(DefaultArrayDeleter<PureT>));
101	  }
102	  /**
103	   * 判断当前Chain中保存的数据是否有deleter
104	   * @return true代表含有deleter
105	   */
106	  bool HasDeleter() const {
107	    return any_value_.deleter != nullptr;
108	  }
109	
110	 private:
111	  template <typename T>
112	  static void DefaultArrayDeleter(T *data) {
113	    delete[] data;
114	  }
115	
116	  template <typename T>
117	  static void DefaultDeleter(T *data) {
118	    delete data;
119	  }
120	
121	  void FreeResource() {
122	    if (any_value_.deleter != nullptr) {
123	      any_value_.deleter(any_value_.data.pointer);
124	    }
125	  }
126	
127	  AsyncAnyValue any_value_;
128	};
