131	class KernelContext {
132	 public:
133	  /**
134	   * 获取kernel的输入数量
135	   * @return kernel的输入数量
136	   */
137	  size_t GetInputNum() const {
138	    return context_.input_size;
139	  }
140	  /**
141	   * 获取kernel的输出数量
142	   * @return kernel的输出数量
143	   */
144	  size_t GetOutputNum() const {
145	    return context_.output_size;
146	  }
147	  /**
148	   * 获取输入的Chain指针
149	   * @param i kernel的输入index
150	   * @return 输入Chain的指针
151	   */
152	  const Chain *GetInput(const size_t i) const {
153	    if (i >= context_.input_size) {
154	      return nullptr;
155	    }
156	    return reinterpret_cast<const Chain *>(context_.values[i]);
157	  }
158	  /**
159	   * 获取输入的Chain指针
160	   * @param i kernel的输入index
161	   * @return 输入Chain的指针
162	   */
163	  Chain *MutableInput(const size_t i) const {
164	    if (i >= context_.input_size) {
165	      return nullptr;
166	    }
167	    return reinterpret_cast<Chain *>(context_.values[i]);
168	  }
169	  /**
170	   * 获取输出的Chain指针
171	   * @param i kernel的输出index
172	   * @return 输出Chain的指针
173	   */
174	  Chain *GetOutput(const size_t i) {
175	    if (i >= context_.output_size) {
176	      return nullptr;
177	    }
178	    return reinterpret_cast<Chain *>(context_.values[context_.input_size + i]);
179	  }
180	  /**
181	   * 获取输出的Chain指针
182	   * @param i kernel的输出index
183	   * @return 输出Chain的指针
184	   */
185	  const Chain *GetOutput(const size_t i) const {
186	    if (i >= context_.output_size) {
187	      return nullptr;
188	    }
189	    return reinterpret_cast<const Chain *>(context_.values[context_.input_size + i]);
190	  }
191	  Chain *GetOutput2(const size_t i) {
192	    if (i >= context_.output_size) {
193	      return nullptr;
194	    }
195	    return reinterpret_cast<Chain *>(context_.output_start[i]);
196	  }
197	  /**
198	   * 获取输入数据的值，本函数首先获取输入Chain，然后从输入Chain中获取值
199	   * @tparam T 值的类型
200	   * @param i kernel的输入index
201	   * @return 输入的值
202	   */
203	  template <typename T>
204	  const T GetInputValue(size_t i) const {
205	    const auto av = GetInput(i);
206	    if (av == nullptr) {
207	      return {};
208	    }
209	    return av->GetValue<T>();
210	  }
211	  /**
212	   * 获取输入数据的指针，本函数首先获取输入Chain，然后从输入Chain中获取指针
213	   * @tparam T 值的类型
214	   * @param i kernel的输入index
215	   * @return 输入数据的指针
216	   */
217	  template <typename T>
218	  const T *GetInputPointer(size_t i) const {
219	    const auto av = GetInput(i);
220	    if (av == nullptr) {
221	      return nullptr;
222	    }
223	    return av->GetPointer<T>();
224	  }
225	  /**
226	   * 获取输入数据的指针，本函数首先获取输入Chain，然后从输入Chain中获取指针
227	   * @tparam T 值的类型
228	   * @param i kernel的输入index
229	   * @return 输入数据的指针
230	   */
231	  template <typename T>
232	  auto MutableInputPointer(size_t i) const -> T * {
233	    const auto av = MutableInput(i);
234	    if (av == nullptr) {
235	      return nullptr;
236	    }
237	    return av->GetPointer<T>();
